#!/usr/bin/env bash
# Generate .github/labeler.yml from repo layout (lives next to the output).
#
# Convention: path labels are CLI commands only.
#   - each directory under src/cli/<area>/ → area:<area>
#   - src/DistSSHKit/argv/<area>* → same area (drive_args.jl, size_report.jl, …)
#   - kit modules explain / demos → area:explain, area:demos
#   - product tests under test/unit and test/integration → that area
#   - SSH E2E entry (`test/e2e.jl`, `test/support/ssh_e2e.jl`) also gets each
#     CLI area that has src/cli/<area> (the suite is those commands on real SSH)
#   - shared kit, test harness, docs, README/NEWS, and .github stay unlabeled
# Do not emit `!` globs: labeler ORs them as "not this path" and tags
# unrelated files.
#
# When a CLI area is added or renamed, regenerate labeler.yml and commit both.
#
# Usage:
#   ./.github/gen-labeler.sh           # write .github/labeler.yml
#   ./.github/gen-labeler.sh --check   # exit 1 if committed file is stale
set -euo pipefail

ROOT="$(cd "$(dirname "$0")/.." && pwd)"
OUT="${ROOT}/.github/labeler.yml"

areas=()
for dir in "${ROOT}/src/cli"/*/; do
  [[ -d "$dir" ]] || continue
  name="$(basename "$dir")"
  [[ "$name" == _* ]] && continue
  areas+=("$name")
done
# Modules without src/cli/<area>/ — still first-class path areas.
areas+=(explain demos)
IFS=$'\n' areas_sorted=($(printf '%s\n' "${areas[@]:-}" | LC_ALL=C sort -u))
unset IFS

tmp="$(mktemp)"
trap 'rm -f "$tmp"' EXIT

{
  cat <<'EOF'
# AUTO-GENERATED by .github/gen-labeler.sh — do not edit by hand.
# Command areas only. Shared kit, harness, docs, and CI stay unlabeled.
# https://github.com/actions/labeler
EOF

  shopt -s nullglob
  for area in "${areas_sorted[@]:-}"; do
    cat <<EOF

"area:${area}":
  - changed-files:
      - any-glob-to-any-file:
          - "src/DistSSHKit/${area}/**"
          - "src/DistSSHKit/${area}.*"
          - "src/DistSSHKit/argv/${area}*"
          - "src/cli/${area}/**"
          - "src/cli/${area}.*"
          - "test/**/${area}/**"
          - "test/**/${area}.*"
          - "test/fixtures/${area}*"
EOF
    if [[ -e "${ROOT}/src/cli/${area}.jl" || -d "${ROOT}/src/cli/${area}" ]]; then
      cat <<'EOF'
          - "test/e2e.jl"
          - "test/support/ssh_e2e.jl"
EOF
    fi
    # Bundled demos live under repo-root demos/ (not only DistSSHKit/demos.jl).
    if [[ "$area" == "demos" ]]; then
      cat <<'EOF'
          - "demos/**"
EOF
    fi
  done
} >"$tmp"

# Each src/cli/<area> file must match that area. Other paths may stay unlabeled.
coverage_ok=1
if command -v python3 >/dev/null 2>&1; then
  if ! python3 - "$ROOT" "$tmp" <<'PY'
import re
import subprocess
import sys
from pathlib import Path

root, yml = Path(sys.argv[1]), Path(sys.argv[2])
text = yml.read_text(encoding="utf-8")
dropped = ("area:docs", "area:project-docs", "area:ci", "area:test", "area:kit")
for name in dropped:
    if f'"{name}"' in text:
        print(f"dropped label still generated: {name}", file=sys.stderr)
        sys.exit(1)

by_label = {}
current = None
for line in text.splitlines():
    m = re.match(r'^"area:([^"]+)":\s*$', line)
    if m:
        current = m.group(1)
        by_label.setdefault(current, [])
        continue
    m = re.match(r'^\s+- "([^"]+)"\s*$', line)
    if m and current:
        by_label[current].append(m.group(1))
if not by_label:
    print("no area rules in generated labeler.yml", file=sys.stderr)
    sys.exit(1)

def to_re(glob):
    i, out = 0, []
    while i < len(glob):
        if glob.startswith("**/", i):
            out.append("(?:.*/)?")
            i += 3
            continue
        if glob.startswith("**", i):
            out.append(".*")
            i += 2
            continue
        if glob[i] == "*":
            out.append("[^/]*")
            i += 1
            continue
        out.append(re.escape(glob[i]))
        i += 1
    return re.compile("^" + "".join(out) + "$")

compiled = {lab: [to_re(g) for g in globs] for lab, globs in by_label.items()}
files = subprocess.check_output(
    ["git", "-C", str(root), "ls-files", "-z", "src/cli"], text=True
).split("\0")
missing = []
for path in files:
    if not path:
        continue
    parts = path.split("/")
    if len(parts) < 3:
        continue
    area = parts[2]
    if area.endswith(".jl"):
        area = area[:-3]
    rxs = compiled.get(area)
    if not rxs or not any(rx.match(path) for rx in rxs):
        missing.append(path)
if missing:
    print("CLI paths missing their area label:", file=sys.stderr)
    for p in missing:
        print(f"  {p}", file=sys.stderr)
    sys.exit(1)
PY
  then
    coverage_ok=0
  fi
fi

mkdir -p "$(dirname "$OUT")"

if [[ "${1:-}" == "--check" ]]; then
  if [[ "$coverage_ok" -ne 1 ]]; then
    exit 1
  fi
  if [[ ! -f "$OUT" ]]; then
    echo "missing $OUT — run ./.github/gen-labeler.sh" >&2
    exit 1
  fi
  if ! diff -u "$OUT" "$tmp" >&2; then
    echo "stale labeler.yml — run ./.github/gen-labeler.sh and commit" >&2
    exit 1
  fi
  echo "labeler.yml up to date"
  exit 0
fi

if [[ "$coverage_ok" -ne 1 ]]; then
  exit 1
fi

cp "$tmp" "$OUT"
echo "wrote $OUT (${#areas_sorted[@]} command areas)"
